(() => {
  const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
  const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
  const money=StoreDB.money;
  let db=StoreDB.load(), currentPage='dashboard', editingProduct=null, editorState=null, currentOrderId=null, currentReviewId=null;
  const statusLabels={new:'New Order',confirmed:'Customer Confirmed',submitted:'Submitted to A to Z',processing:'Processing',shipped:'Shipped',delivered:'Delivered',cancelled:'Cancelled',returned:'Returned'};
  const statusOptions=Object.entries(statusLabels);

  async function refresh(){db=await StoreDB.loadAdmin();return db}
  function save(){return StoreDB.save(db)}
  function toast(msg){const e=$('#toast');e.textContent=msg;e.classList.add('show');clearTimeout(window.__at);window.__at=setTimeout(()=>e.classList.remove('show'),2400)}
  function openModal(id){document.getElementById(id)?.classList.add('open');document.body.classList.add('no-scroll')}
  function closeModal(id){document.getElementById(id)?.classList.remove('open');if(!document.querySelector('.modal.open'))document.body.classList.remove('no-scroll')}
  function grossProfitProduct(p){return Number(p.price||0)-Number(p.supplierCost||0)-Number(p.shipping||0)-Number(p.otherCost||0)}
  function netProfitProduct(p){return grossProfitProduct(p)-Number(p.adCost||0)}
  function orderGross(o){return (o.items||[]).reduce((a,i)=>a+(Number(i.price)-Number(i.supplierCost||0)-Number(i.shipping||0)-Number(i.otherCost||0))*Number(i.qty||1),0)}
  function orderNet(o){return (o.items||[]).reduce((a,i)=>a+(Number(i.price)-Number(i.supplierCost||0)-Number(i.shipping||0)-Number(i.otherCost||0)-Number(i.adCost||0))*Number(i.qty||1),0)}
  function formatDate(s){if(!s)return '—';try{return new Date(s).toLocaleDateString('en-LK',{year:'numeric',month:'short',day:'numeric'})}catch{return s}}
  function productImage(p){return p.media?.images?.[0]||''}
  function productName(id){return db.products.find(p=>p.id===id)?.name||'Deleted product'}
  function empty(title,text,button=''){return `<div class="admin-empty"><div>✦</div><h3>${esc(title)}</h3><p>${esc(text)}</p>${button}</div>`}
  function statCard(label,value,sub='',tone=''){return `<article class="kpi ${tone}"><span>${esc(label)}</span><strong>${value}</strong>${sub?`<small>${esc(sub)}</small>`:''}</article>`}

  async function loginInit(){
    if(!StoreDB.configured()){
      $('#adminLogin').classList.remove('hidden');$('#adminApp').classList.add('hidden');
      const note=$('#adminLoginForm small');if(note)note.textContent='Supabase setup required. See SUPABASE_SETUP.md in the ZIP.';
    }else{
      try{const logged=await StoreDB.adminIsSignedIn();$('#adminLogin').classList.toggle('hidden',logged);$('#adminApp').classList.toggle('hidden',!logged);if(logged)await renderPage()}catch(e){toast(e.message)}
    }
    $('#adminLoginForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),btn=e.currentTarget.querySelector('button');btn.disabled=true;btn.textContent='Signing in...';try{await StoreDB.signInAdmin(f.get('email').trim(),f.get('password'));$('#adminLogin').classList.add('hidden');$('#adminApp').classList.remove('hidden');await renderPage();toast('Admin signed in')}catch(err){toast(err.message)}finally{btn.disabled=false;btn.textContent='Login to Admin'}};
    $('#logoutAdmin').onclick=async()=>{await StoreDB.signOut();location.reload()};
  }
  function bindShell(){
    $$('#adminNav [data-page]').forEach(b=>b.onclick=()=>{currentPage=b.dataset.page;$$('#adminNav [data-page]').forEach(x=>x.classList.toggle('active',x===b));document.body.classList.remove('sidebar-open');renderPage()});
    $('#adminMenu').onclick=()=>document.body.classList.toggle('sidebar-open');$('#quickAddProduct').onclick=()=>openProductEditor();
    $$('[data-close]').forEach(b=>b.onclick=()=>closeModal(b.dataset.close));
    $('#categoryForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),name=f.get('category').trim();if(!name)return;if(!db.categories.some(c=>c.toLowerCase()===name.toLowerCase())){db.categories.push(name);db.categories.sort();save();renderCategoryList();if($('#productCategory')){const old=$('#productCategory').value;renderEditorCategoryOptions();$('#productCategory').value=name||old}}e.currentTarget.reset()};
    $('#expenseForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);db.expenses.unshift({id:StoreDB.uid('E'),date:f.get('date'),category:f.get('category'),amount:Number(f.get('amount')),note:f.get('note').trim()});save();closeModal('expenseModal');renderPage();toast('Expense saved')};
  }
  function pageTitle(){return ({dashboard:'Dashboard',products:'Products',orders:'Orders',reviews:'Reviews',customers:'Customers',finance:'Finance',reports:'Reports',analytics:'Analytics',offers:'Offers',banners:'Banners',media:'Media Library',settings:'Website Settings'})[currentPage]||'Admin'}
  async function renderPage(){try{await refresh()}catch(e){toast(e.message);return}$('#adminPageTitle').textContent=pageTitle();const map={dashboard:renderDashboard,products:renderProducts,orders:renderOrders,reviews:renderReviews,customers:renderCustomers,finance:renderFinance,reports:renderReports,analytics:renderAnalytics,offers:renderOffers,banners:renderBanners,media:renderMedia,settings:renderSettings};(map[currentPage]||renderDashboard)()}

  function renderDashboard(){
    const sales=db.orders.filter(o=>!['cancelled','returned'].includes(o.status)).reduce((a,o)=>a+Number(o.total||0),0),expected=db.orders.filter(o=>!['cancelled','returned'].includes(o.status)).reduce((a,o)=>a+orderGross(o),0),received=db.orders.reduce((a,o)=>a+Number(o.receivedProfit||0),0),expenses=db.expenses.reduce((a,e)=>a+Number(e.amount||0),0),pending=Math.max(0,expected-received),newOrders=db.orders.filter(o=>o.status==='new').length;
    $('#adminContent').innerHTML=`<div class="welcome-card"><div><span>WELCOME BACK</span><h2>Your Step in Style store is ready.</h2><p>${db.products.length?'Manage today’s products, orders and customer activity.':'Start fresh by adding your first product. Everything is currently empty as requested.'}</p></div><button class="primary-btn" id="dashAddProduct">+ Add Product</button></div><div class="kpi-grid">${statCard('Products',db.products.length,`${db.products.filter(p=>p.status==='published').length} published`)}${statCard('Orders',db.orders.length,`${newOrders} new`)}${statCard('Customers',db.customers.length)}${statCard('Reviews',db.reviews.length,`${db.reviews.filter(r=>r.status==='pending').length} pending`)}${statCard('Sales',money(sales))}${statCard('Expected Profit',money(expected),'before advertising')}${statCard('Received Profit',money(received),'confirmed from A to Z','success')}${statCard('Pending Profit',money(pending))}${statCard('Expenses',money(expenses))}${statCard('Net After Expenses',money(received-expenses),'received profit minus expenses',received-expenses>=0?'success':'danger')}</div><div class="admin-grid-two"><section class="admin-card"><div class="card-head"><div><h3>Recent Orders</h3><p>Your latest customer orders.</p></div><button class="text-btn" data-goto="orders">View all</button></div>${db.orders.length?`<div class="simple-list">${db.orders.slice(0,5).map(o=>`<button data-order="${o.id}"><span><b>${esc(o.id)}</b><small>${esc(o.customer?.name||'')}</small></span><span><b>${money(o.total)}</b><small>${statusLabels[o.status]||o.status}</small></span></button>`).join('')}</div>`:empty('No orders yet','Customer orders will appear here after checkout.')}</section><section class="admin-card"><div class="card-head"><div><h3>Quick Start</h3><p>Recommended setup order.</p></div></div><ol class="quick-list"><li><b>Create categories</b><span>Organize your store.</span></li><li><b>Add your first product</b><span>Title → images → price → description → A to Z details.</span></li><li><b>Preview and publish</b><span>Check the mobile customer page.</span></li><li><b>Receive COD orders</b><span>Orders appear here automatically.</span></li></ol></section></div>`;
    $('#dashAddProduct').onclick=()=>openProductEditor();$$('[data-goto]').forEach(b=>b.onclick=()=>{currentPage=b.dataset.goto;$$('#adminNav [data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===currentPage));renderPage()});$$('[data-order]').forEach(b=>b.onclick=()=>openOrder(b.dataset.order));
  }

  function renderProducts(){
    $('#adminContent').innerHTML=`<div class="page-actions"><div class="search-box admin-search"><span>⌕</span><input id="adminProductSearch" placeholder="Search products..."></div><div><button class="outline-btn" id="manageCategories">Manage Categories</button><button class="primary-btn" id="addProductBtn">+ Add Product</button></div></div><div id="productsArea"></div>`;
    $('#addProductBtn').onclick=()=>openProductEditor();$('#manageCategories').onclick=()=>{renderCategoryList();openModal('categoryModal')};$('#adminProductSearch').oninput=renderProductRows;renderProductRows();
  }
  function renderProductRows(){const q=($('#adminProductSearch')?.value||'').toLowerCase(),list=db.products.filter(p=>[p.name,p.category,p.productCode,p.supplierCode].join(' ').toLowerCase().includes(q)),area=$('#productsArea');if(!list.length){area.innerHTML=empty('No products yet','Add your first Step in Style product. You can upload 1–5 images, videos, build the description, add A to Z details and publish it.','<button class="primary-btn" id="emptyAddProduct">+ Add Your First Product</button>');$('#emptyAddProduct')&&($('#emptyAddProduct').onclick=()=>openProductEditor());return}area.innerHTML=`<div class="table-card"><div class="admin-table products-table"><div class="tr th"><span>Product</span><span>Price</span><span>Status</span><span>Expected Profit</span><span>Actions</span></div>${list.map(p=>`<div class="tr"><span class="admin-product-row">${productImage(p)?`<img src="${esc(productImage(p))}" alt="">`:'<span class="tiny-placeholder">SIS</span>'}<span><b>${esc(p.name)}</b><small>${esc(p.category||'Uncategorized')} • ${p.media?.images?.length||0}/5 images</small></span></span><span><b>${money(p.price)}</b>${p.oldPrice>p.price?`<small><del>${money(p.oldPrice)}</del></small>`:''}</span><span><span class="status-pill ${p.status}">${esc(p.status)}</span></span><span><b class="${grossProfitProduct(p)>=0?'profit-positive':'profit-negative'}">${money(grossProfitProduct(p))}</b><small>Net est. ${money(netProfitProduct(p))}</small></span><span class="row-actions"><button data-edit-product="${p.id}">Edit</button><a href="product.html?id=${encodeURIComponent(p.id)}&preview=1" target="_blank">Preview</a><button data-duplicate-product="${p.id}">Duplicate</button><button data-archive-product="${p.id}">${p.status==='archived'?'Unarchive':'Archive'}</button><button class="danger" data-delete-product="${p.id}">Delete</button></span></div>`).join('')}</div></div>`;$$('[data-edit-product]').forEach(b=>b.onclick=()=>openProductEditor(b.dataset.editProduct));$$('[data-duplicate-product]').forEach(b=>b.onclick=()=>duplicateProduct(b.dataset.duplicateProduct));$$('[data-archive-product]').forEach(b=>b.onclick=()=>{const p=db.products.find(x=>x.id===b.dataset.archiveProduct);p.status=p.status==='archived'?'draft':'archived';save();renderProductRows()});$$('[data-delete-product]').forEach(b=>b.onclick=()=>{if(confirm('Delete this product permanently?')){const id=b.dataset.deleteProduct;StoreDB.deleteProduct(id).then(()=>{db.products=db.products.filter(x=>x.id!==id);renderProductRows();toast('Product deleted')}).catch(e=>toast(e.message))}})}
  function duplicateProduct(id){const p=db.products.find(x=>x.id===id);if(!p)return;const copy=JSON.parse(JSON.stringify(p));copy.id=StoreDB.uid('P');copy.name+=' Copy';copy.slug=StoreDB.slugify(copy.name);copy.status='draft';copy.createdAt=new Date().toISOString();copy.updatedAt=copy.createdAt;db.products.unshift(copy);save();renderProductRows();toast('Product duplicated as draft')}

  function renderCategoryList(){const wrap=$('#categoryList');if(!wrap)return;wrap.innerHTML=db.categories.length?db.categories.map(c=>`<div><span>${esc(c)}</span><button data-delete-cat="${esc(c)}">Delete</button></div>`).join(''):'<div class="empty-inline">No categories yet.</div>';$$('[data-delete-cat]').forEach(b=>b.onclick=()=>{const c=b.dataset.deleteCat;if(db.products.some(p=>p.category===c))return toast('This category is used by a product. Change that product first.');StoreDB.deleteCategory(c).then(()=>{db.categories=db.categories.filter(x=>x!==c);renderCategoryList()}).catch(e=>toast(e.message))})}

  function emptyProduct(){return {id:StoreDB.uid('P'),name:'',slug:'',shortDescription:'',category:'',productCode:'',brand:'',price:0,oldPrice:0,supplier:'A to Z Dropshipping',supplierCost:0,shipping:0,otherCost:0,adCost:0,supplierCode:'',supplierUrl:'',stock:'available',qty:999,status:'draft',featured:false,newArrival:false,badge:'',views:0,media:{images:[],videos:[]},descriptionBlocks:[],variants:[],seo:{title:'',description:'',keywords:''},createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()}}
  async function openProductEditor(id=''){try{await refresh()}catch(e){toast(e.message);return}editingProduct=id?db.products.find(p=>p.id===id):null;editorState=JSON.parse(JSON.stringify(editingProduct||emptyProduct()));$('#editorHeading').textContent=editingProduct?'Edit Product':'Add New Product';renderProductEditor();openModal('productEditorModal');setTimeout(()=>$('#productTitle')?.focus(),100)}
  function renderEditorCategoryOptions(){const sel=$('#productCategory');if(!sel)return;const current=sel.value||editorState.category;sel.innerHTML='<option value="">Choose category...</option>'+db.categories.map(c=>`<option>${esc(c)}</option>`).join('');sel.value=current||''}
  function renderProductEditor(){
    const p=editorState;
    $('#productEditor').innerHTML=`<section class="editor-section"><div class="editor-title"><span>1</span><div><h3>Basic Information</h3><p>Start with the details customers see first.</p></div></div><div class="form-grid"><label class="field full"><span>Product Title *</span><input id="productTitle" value="${esc(p.name)}" placeholder="e.g. Rechargeable LED Torch"></label><label class="field full"><span>Short Description</span><textarea id="productShort" placeholder="One or two lines that quickly explain the product.">${esc(p.shortDescription)}</textarea></label><label class="field"><span>Category</span><div class="field-inline"><select id="productCategory"></select><button class="mini-btn" id="inlineAddCategory" type="button">+ New</button></div></label><label class="field"><span>Product Code</span><input id="productCode" value="${esc(p.productCode)}" placeholder="SIS-001"></label></div></section>
    <section class="editor-section"><div class="editor-title"><span>2</span><div><h3>Images & Videos</h3><p>Upload 1–5 product images. The first image is the main image.</p></div></div><div class="upload-drop" id="imageDrop"><input id="productImagesInput" type="file" accept="image/*" multiple hidden><div>🖼️</div><b>Drag product images here</b><span>or</span><button class="outline-btn" id="browseImages" type="button">Browse Images</button><small id="imageCounter">${p.media.images.length} / 5 images uploaded</small></div><div id="productImageEditor" class="media-editor"></div><div class="sub-editor"><div class="sub-head"><div><h4>Product Videos</h4><p>Add YouTube/direct video URLs or upload MP4/WebM video (up to 50 MB).</p></div></div><div class="media-add-row"><input id="productVideoUrl" placeholder="Paste YouTube or direct video URL"><button class="outline-btn" id="addVideoUrl" type="button">Add Video</button><label class="outline-btn file-button">Upload Video<input id="productVideoFile" type="file" accept="video/mp4,video/webm" hidden></label></div><div id="productVideoEditor" class="media-editor"></div></div></section>
    <section class="editor-section"><div class="editor-title"><span>3</span><div><h3>Customer Pricing</h3><p>Set the price customers see. Discount is calculated automatically.</p></div></div><div class="form-grid"><label class="field"><span>Selling Price (Rs.) *</span><input id="productPrice" type="number" min="0" value="${Number(p.price||0)}"></label><label class="field"><span>Old / Compare Price (Rs.)</span><input id="productOldPrice" type="number" min="0" value="${Number(p.oldPrice||0)}"></label></div><div id="discountPreview" class="calculation-strip"></div></section>
    <section class="editor-section"><div class="editor-title"><span>4</span><div><h3>Product Description</h3><p>Build the page using easy content blocks. Only Admin can edit these blocks.</p></div></div><div class="description-toolbar"><button type="button" data-add-block="heading">+ Heading</button><button type="button" data-add-block="text">+ Text</button><button type="button" data-add-block="image">+ Image</button><button type="button" data-add-block="video">+ Video</button><button type="button" data-add-block="features">+ Features</button><button type="button" data-add-block="specs">+ Specifications</button></div><div id="descriptionBlocks"></div><div class="description-empty-hint ${p.descriptionBlocks.length?'hidden':''}" id="descriptionHint">Add a heading, text, image, video, features or specifications. Blocks can be moved up and down.</div></section>
    <section class="editor-section private-section"><div class="editor-title"><span>5</span><div><h3>A to Z Supplier Information</h3><p>🔒 Private — customers never see these details.</p></div></div><div class="form-grid"><label class="field"><span>Supplier</span><input value="A to Z Dropshipping" disabled></label><label class="field"><span>A to Z Product Code</span><input id="supplierCode" value="${esc(p.supplierCode)}"></label><label class="field full"><span>A to Z Product URL</span><input id="supplierUrl" type="url" value="${esc(p.supplierUrl)}" placeholder="https://..."></label><label class="field"><span>A to Z Product Price (Rs.)</span><input id="supplierCost" type="number" min="0" value="${Number(p.supplierCost||0)}"></label><label class="field"><span>Shipping Fee (Rs.)</span><input id="supplierShipping" type="number" min="0" value="${Number(p.shipping||0)}"></label><label class="field"><span>Other Cost (Rs.)</span><input id="otherCost" type="number" min="0" value="${Number(p.otherCost||0)}"></label><label class="field"><span>Expected Ad Cost per Sale (Rs.)</span><input id="adCost" type="number" min="0" value="${Number(p.adCost||0)}"></label></div><div id="profitPreview" class="profit-calculator"></div></section>
    <section class="editor-section"><div class="editor-title"><span>6</span><div><h3>Availability & Options</h3><p>Choose availability and add optional variations.</p></div></div><div class="form-grid"><label class="field"><span>Availability</span><select id="productStock"><option value="available">Available</option><option value="limited">Limited Availability</option><option value="out">Out of Stock</option><option value="coming">Coming Soon</option></select></label><label class="field"><span>Quantity / Stock Note</span><input id="productQty" type="number" min="0" value="${p.qty===999?'':Number(p.qty||0)}" placeholder="Leave blank if not tracking quantity"></label><label class="field"><span>Badge</span><input id="productBadge" value="${esc(p.badge)}" placeholder="Best Seller / New / Limited"></label><div class="field check-field"><label><input id="productFeatured" type="checkbox" ${p.featured?'checked':''}> Featured product</label><label><input id="productNewArrival" type="checkbox" ${p.newArrival?'checked':''}> New arrival</label></div><label class="field full"><span>Variations</span><textarea id="productVariants" placeholder="One option per line. Example:\nColor: Black, Blue, Red\nSize: S, M, L">${esc((p.variants||[]).map(v=>`${v.name}: ${(v.values||[]).join(', ')}`).join('\n'))}</textarea><small>Optional. Customers will see dropdowns on the product page.</small></label></div></section>
    <section class="editor-section"><div class="editor-title"><span>7</span><div><h3>SEO</h3><p>Optional search-engine information.</p></div></div><div class="form-grid"><label class="field full"><span>SEO Title</span><input id="seoTitle" value="${esc(p.seo?.title||'')}"></label><label class="field full"><span>SEO Description</span><textarea id="seoDescription">${esc(p.seo?.description||'')}</textarea></label><label class="field full"><span>Keywords</span><input id="seoKeywords" value="${esc(p.seo?.keywords||'')}" placeholder="torch, rechargeable light, Sri Lanka"></label></div></section><div class="editor-actions sticky"><button class="outline-btn" id="bottomDraft">Save Draft</button><button class="outline-btn" id="bottomPreview">Preview</button><button class="primary-btn" id="bottomPublish">Publish Product</button></div>`;
    renderEditorCategoryOptions();$('#productStock').value=p.stock;renderImageEditor();renderVideoEditor();renderBlocks();bindEditor();updateCalculations();
  }
  function bindEditor(){
    $('#inlineAddCategory').onclick=()=>{renderCategoryList();openModal('categoryModal')};$('#browseImages').onclick=()=>$('#productImagesInput').click();$('#productImagesInput').onchange=e=>addProductImages(e.target.files);const drop=$('#imageDrop');['dragenter','dragover'].forEach(n=>drop.addEventListener(n,e=>{e.preventDefault();drop.classList.add('dragging')}));['dragleave','drop'].forEach(n=>drop.addEventListener(n,e=>{e.preventDefault();drop.classList.remove('dragging')}));drop.addEventListener('drop',e=>addProductImages(e.dataTransfer.files));
    $('#addVideoUrl').onclick=()=>{const v=$('#productVideoUrl').value.trim();if(!v)return;editorState.media.videos.push(v);$('#productVideoUrl').value='';renderVideoEditor()};$('#productVideoFile').onchange=e=>addProductVideo(e.target.files[0]);
    $$('[data-add-block]').forEach(b=>b.onclick=()=>addDescriptionBlock(b.dataset.addBlock));
    ['productPrice','productOldPrice','supplierCost','supplierShipping','otherCost','adCost'].forEach(id=>$('#'+id).addEventListener('input',updateCalculations));
    $('#saveDraftBtn').onclick=()=>saveProductFromEditor('draft');$('#publishProductBtn').onclick=()=>saveProductFromEditor('published');$('#previewProductBtn').onclick=()=>previewProduct();$('#bottomDraft').onclick=()=>saveProductFromEditor('draft');$('#bottomPublish').onclick=()=>saveProductFromEditor('published');$('#bottomPreview').onclick=()=>previewProduct();
  }
  async function compressImage(file,max=1600){if(!file.type.startsWith('image/'))throw Error('Please choose image files only.');if(file.size>8*1024*1024)throw Error(`${file.name} is too large. Maximum source size is 8 MB.`);const bmp=await createImageBitmap(file),scale=Math.min(1,max/bmp.width),c=document.createElement('canvas');c.width=Math.max(1,Math.round(bmp.width*scale));c.height=Math.max(1,Math.round(bmp.height*scale));c.getContext('2d').drawImage(bmp,0,0,c.width,c.height);const blob=await new Promise(r=>c.toBlob(r,'image/webp',.82));return new File([blob],(file.name.replace(/\.[^.]+$/,'')||'product')+'.webp',{type:'image/webp'})}
  async function addProductImages(files){try{const room=5-editorState.media.images.length;if(room<=0)return toast('Maximum 5 product images.');toast('Uploading images...');for(const f of [...files].slice(0,room)){const compressed=await compressImage(f);editorState.media.images.push(await StoreDB.uploadAdminMedia('product-images',editorState.id,compressed))}renderImageEditor();toast('Images uploaded')}catch(e){toast(e.message)}}
  async function addProductVideo(file){if(!file)return;try{if(!['video/mp4','video/webm'].includes(file.type))throw Error('Use MP4 or WebM video.');if(file.size>50*1024*1024)throw Error('Product video must be under 50 MB. Use YouTube for larger videos.');toast('Uploading video...');editorState.media.videos.push(await StoreDB.uploadAdminMedia('product-videos',editorState.id,file));renderVideoEditor();toast('Video uploaded')}catch(e){toast(e.message)}}
  function renderImageEditor(){const wrap=$('#productImageEditor');if(!wrap)return;$('#imageCounter').textContent=`${editorState.media.images.length} / 5 images uploaded`;wrap.innerHTML=editorState.media.images.map((src,i)=>`<div class="media-tile"><img src="${src}" alt="Product image"><div class="media-tile-label">${i===0?'★ MAIN IMAGE':`Image ${i+1}`}</div><div class="media-controls"><button data-img-left="${i}" ${i===0?'disabled':''}>←</button><button data-img-main="${i}">Set Main</button><button data-img-right="${i}" ${i===editorState.media.images.length-1?'disabled':''}>→</button><button class="danger" data-img-remove="${i}">Delete</button></div></div>`).join('');$$('[data-img-left]').forEach(b=>b.onclick=()=>moveArray(editorState.media.images,Number(b.dataset.imgLeft),-1,renderImageEditor));$$('[data-img-right]').forEach(b=>b.onclick=()=>moveArray(editorState.media.images,Number(b.dataset.imgRight),1,renderImageEditor));$$('[data-img-main]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.imgMain),x=editorState.media.images.splice(i,1)[0];editorState.media.images.unshift(x);renderImageEditor()});$$('[data-img-remove]').forEach(b=>b.onclick=()=>{editorState.media.images.splice(Number(b.dataset.imgRemove),1);renderImageEditor()})}
  function ytEmbed(url){try{const u=new URL(url);if(u.hostname.includes('youtu.be'))return 'https://www.youtube.com/embed/'+u.pathname.slice(1);if(u.hostname.includes('youtube.com'))return 'https://www.youtube.com/embed/'+u.searchParams.get('v')}catch{}return ''}
  function videoPreview(src){const yt=ytEmbed(src);return yt?`<iframe src="${esc(yt)}" title="Video" allowfullscreen></iframe>`:`<video src="${esc(src)}" controls playsinline></video>`}
  function renderVideoEditor(){const wrap=$('#productVideoEditor');if(!wrap)return;wrap.innerHTML=editorState.media.videos.length?editorState.media.videos.map((src,i)=>`<div class="media-tile">${videoPreview(src)}<div class="media-tile-label">Video ${i+1}</div><div class="media-controls"><button class="danger" data-video-remove="${i}">Delete</button></div></div>`).join(''):'<div class="empty-inline">No product videos added.</div>';$$('[data-video-remove]').forEach(b=>b.onclick=()=>{editorState.media.videos.splice(Number(b.dataset.videoRemove),1);renderVideoEditor()})}
  function moveArray(arr,i,d,render){const j=i+d;if(j<0||j>=arr.length)return;[arr[i],arr[j]]=[arr[j],arr[i]];render()}
  function addDescriptionBlock(type){const base={id:StoreDB.uid('B'),type};if(type==='heading')base.content='';if(type==='text'){base.content='';base.html=''}if(type==='features'){base.title='Main Features';base.content=''}if(type==='specs'){base.title='Specifications';base.content=''}if(type==='image'||type==='video'){base.src='';base.caption=''}editorState.descriptionBlocks.push(base);renderBlocks();$('#descriptionHint')?.classList.add('hidden')}
  function renderBlocks(){const wrap=$('#descriptionBlocks');if(!wrap)return;wrap.innerHTML=editorState.descriptionBlocks.map((b,i)=>`<div class="description-block" data-block-index="${i}"><div class="block-head"><div><span class="drag-handle">☰</span><b>${b.type.charAt(0).toUpperCase()+b.type.slice(1)} Block</b></div><div><button data-block-up="${i}" ${i===0?'disabled':''}>↑</button><button data-block-down="${i}" ${i===editorState.descriptionBlocks.length-1?'disabled':''}>↓</button><button class="danger" data-block-delete="${i}">Delete</button></div></div>${blockEditor(b,i)}</div>`).join('');$$('[data-block-up]').forEach(b=>b.onclick=()=>moveBlock(Number(b.dataset.blockUp),-1));$$('[data-block-down]').forEach(b=>b.onclick=()=>moveBlock(Number(b.dataset.blockDown),1));$$('[data-block-delete]').forEach(b=>b.onclick=()=>{editorState.descriptionBlocks.splice(Number(b.dataset.blockDelete),1);renderBlocks()});$$('[data-block-input]').forEach(el=>el.addEventListener('input',updateBlockFromInput));$$('[data-block-title]').forEach(el=>el.addEventListener('input',updateBlockFromInput));$$('[data-rich-editor]').forEach(el=>el.addEventListener('input',()=>{const b=editorState.descriptionBlocks[Number(el.dataset.richEditor)];b.html=el.innerHTML;b.content=el.textContent}));$$('[data-format]').forEach(btn=>btn.onclick=()=>{const ed=btn.closest('.rich-editor-wrap').querySelector('[contenteditable]');ed.focus();document.execCommand(btn.dataset.format,false,null);ed.dispatchEvent(new Event('input'))});$$('[data-block-file]').forEach(inp=>inp.onchange=e=>addBlockFile(Number(inp.dataset.blockFile),e.target.files[0]));$$('[data-block-url-add]').forEach(btn=>btn.onclick=()=>{const i=Number(btn.dataset.blockUrlAdd),input=btn.closest('.block-media-input').querySelector('input[type=url]');editorState.descriptionBlocks[i].src=input.value.trim();renderBlocks()})}
  function blockEditor(b,i){
    if(b.type==='heading')return `<label class="field"><span>Heading text</span><input data-block-input="${i}" value="${esc(b.content||'')}" placeholder="e.g. Powerful LED Performance"></label>`;
    if(b.type==='text')return `<div class="rich-editor-wrap"><div class="mini-toolbar"><button type="button" data-format="bold"><b>B</b></button><button type="button" data-format="italic"><i>I</i></button><button type="button" data-format="underline"><u>U</u></button><button type="button" data-format="insertUnorderedList">• List</button><button type="button" data-format="insertOrderedList">1. List</button></div><div class="rich-edit" contenteditable="true" data-rich-editor="${i}" data-placeholder="Write product description here...">${b.html||esc(b.content||'')}</div></div>`;
    if(b.type==='features')return `<label class="field"><span>Section title</span><input data-block-title="${i}" value="${esc(b.title||'Main Features')}"></label><label class="field"><span>One feature per line</span><textarea data-block-input="${i}" placeholder="High brightness LED\nRechargeable battery\nPortable design">${esc(b.content||'')}</textarea></label>`;
    if(b.type==='specs')return `<label class="field"><span>Section title</span><input data-block-title="${i}" value="${esc(b.title||'Specifications')}"></label><label class="field"><span>One specification per line using Name: Value</span><textarea data-block-input="${i}" placeholder="Battery: Rechargeable\nMaterial: ABS\nColor: Black">${esc(b.content||'')}</textarea></label>`;
    if(b.type==='image')return `<div class="block-media-input">${b.src?`<img class="block-preview-image" src="${esc(b.src)}" alt="">`:''}<label class="outline-btn file-button">${b.src?'Replace Image':'Upload Description Image'}<input data-block-file="${i}" type="file" accept="image/*" hidden></label><label class="field"><span>Caption</span><input data-block-input="${i}" data-field="caption" value="${esc(b.caption||'')}"></label></div>`;
    if(b.type==='video')return `<div class="block-media-input">${b.src?`<div class="block-video-preview">${videoPreview(b.src)}</div>`:''}<div class="media-add-row"><input type="url" placeholder="YouTube/direct video URL" value="${b.src&&!b.src.startsWith('data:')?esc(b.src):''}"><button class="outline-btn" type="button" data-block-url-add="${i}">Use URL</button><label class="outline-btn file-button">Upload Video<input data-block-file="${i}" type="file" accept="video/mp4,video/webm" hidden></label></div><label class="field"><span>Caption</span><input data-block-input="${i}" data-field="caption" value="${esc(b.caption||'')}"></label></div>`;return ''
  }
  function moveBlock(i,d){const j=i+d;if(j<0||j>=editorState.descriptionBlocks.length)return;[editorState.descriptionBlocks[i],editorState.descriptionBlocks[j]]=[editorState.descriptionBlocks[j],editorState.descriptionBlocks[i]];renderBlocks()}
  function updateBlockFromInput(e){const i=Number(e.target.dataset.blockInput??e.target.dataset.blockTitle),b=editorState.descriptionBlocks[i];if(e.target.dataset.blockTitle!==undefined)b.title=e.target.value;else if(e.target.dataset.field==='caption')b.caption=e.target.value;else b.content=e.target.value}
  async function addBlockFile(i,file){if(!file)return;const b=editorState.descriptionBlocks[i];try{toast('Uploading description media...');if(b.type==='image'){const compressed=await compressImage(file);b.src=await StoreDB.uploadAdminMedia('description-media',editorState.id,compressed)}else{if(!['video/mp4','video/webm'].includes(file.type))throw Error('Use MP4 or WebM video.');if(file.size>50*1024*1024)throw Error('Description video must be under 50 MB.');b.src=await StoreDB.uploadAdminMedia('description-media',editorState.id,file)}renderBlocks();toast('Description media uploaded')}catch(e){toast(e.message)}}
  function updateCalculations(){const price=Number($('#productPrice')?.value||0),old=Number($('#productOldPrice')?.value||0),supplier=Number($('#supplierCost')?.value||0),ship=Number($('#supplierShipping')?.value||0),other=Number($('#otherCost')?.value||0),ad=Number($('#adCost')?.value||0),gross=price-supplier-ship-other,net=gross-ad;const disc=$('#discountPreview');if(disc)disc.innerHTML=old>price&&price>0?`<span>Discount</span><b>${Math.round((old-price)/old*100)}%</b><span>Customer saves</span><b>${money(old-price)}</b>`:'<span>No active discount</span>';const pro=$('#profitPreview');if(pro)pro.innerHTML=`<div><span>Selling Price</span><b>${money(price)}</b></div><div><span>Supplier Price</span><b>− ${money(supplier)}</b></div><div><span>Shipping</span><b>− ${money(ship)}</b></div><div><span>Other Cost</span><b>− ${money(other)}</b></div><div class="profit-row"><span>Expected Gross Profit</span><strong>${money(gross)}</strong></div><div><span>Advertising Cost</span><b>− ${money(ad)}</b></div><div class="net-row"><span>Estimated Net Profit</span><strong>${money(net)}</strong></div>`}
  function collectProduct(){const parseVariants=()=>($('#productVariants').value||'').split('\n').map(x=>x.trim()).filter(Boolean).map(line=>{const [name,...rest]=line.split(':');return {name:name.trim(),values:rest.join(':').split(',').map(x=>x.trim()).filter(Boolean)}}).filter(v=>v.name&&v.values.length);return {...editorState,name:$('#productTitle').value.trim(),slug:StoreDB.slugify($('#productTitle').value),shortDescription:$('#productShort').value.trim(),category:$('#productCategory').value,productCode:$('#productCode').value.trim(),price:Number($('#productPrice').value||0),oldPrice:Number($('#productOldPrice').value||0),supplierCode:$('#supplierCode').value.trim(),supplierUrl:$('#supplierUrl').value.trim(),supplierCost:Number($('#supplierCost').value||0),shipping:Number($('#supplierShipping').value||0),otherCost:Number($('#otherCost').value||0),adCost:Number($('#adCost').value||0),stock:$('#productStock').value,qty:$('#productQty').value===''?999:Number($('#productQty').value||0),badge:$('#productBadge').value.trim(),featured:$('#productFeatured').checked,newArrival:$('#productNewArrival').checked,variants:parseVariants(),seo:{title:$('#seoTitle').value.trim(),description:$('#seoDescription').value.trim(),keywords:$('#seoKeywords').value.trim()},updatedAt:new Date().toISOString()}}
  function persistEditor(status,showToast=true){const p=collectProduct();p.status=status||p.status;if(!p.name){toast('Add a product title first.');return null}if(p.status==='published'&&p.media.images.length<1){toast('Add at least 1 product image before publishing.');return null}if(p.status==='published'&&p.price<=0){toast('Add a selling price before publishing.');return null}const idx=db.products.findIndex(x=>x.id===p.id);if(idx>=0)db.products[idx]=p;else db.products.unshift(p);save().catch(e=>toast(e.message));editingProduct=p;editorState=JSON.parse(JSON.stringify(p));if(showToast)toast(p.status==='published'?'Product published':'Draft saved');return p}
  function saveProductFromEditor(status){const p=persistEditor(status);if(!p)return;closeModal('productEditorModal');if(currentPage==='products')renderProducts();else renderPage()}
  async function previewProduct(){const p=persistEditor('draft',false);if(!p)return;try{await save();window.open(`product.html?id=${encodeURIComponent(p.id)}&preview=1`,'_blank')}catch(e){toast(e.message)}}

  function renderOrders(){const statuses=['all',...Object.keys(statusLabels)];$('#adminContent').innerHTML=`<div class="filter-row"><div class="search-box admin-search"><span>⌕</span><input id="orderSearch" placeholder="Order ID, customer, phone, A to Z ID..."></div><select id="orderStatusFilter">${statuses.map(s=>`<option value="${s}">${s==='all'?'All statuses':statusLabels[s]}</option>`).join('')}</select></div><div id="ordersArea"></div>`;$('#orderSearch').oninput=renderOrderRows;$('#orderStatusFilter').onchange=renderOrderRows;renderOrderRows()}
  function renderOrderRows(){const q=($('#orderSearch')?.value||'').toLowerCase(),st=$('#orderStatusFilter')?.value||'all',list=db.orders.filter(o=>(st==='all'||o.status===st)&&[o.id,o.customer?.name,o.customer?.phone,o.supplierOrderId].join(' ').toLowerCase().includes(q)),area=$('#ordersArea');if(!list.length){area.innerHTML=empty('No orders found','Customer COD orders will appear here automatically.');return}area.innerHTML=`<div class="table-card"><div class="admin-table orders-table"><div class="tr th"><span>Order</span><span>Customer</span><span>Total</span><span>Status</span><span>Profit</span><span>Action</span></div>${list.map(o=>`<div class="tr"><span><b>${esc(o.id)}</b><small>${formatDate(o.date)}</small></span><span><b>${esc(o.customer?.name||'')}</b><small>${esc(o.customer?.phone||'')}</small></span><span><b>${money(o.total)}</b><small>${o.items?.length||0} item(s)</small></span><span><span class="status-pill ${o.status}">${statusLabels[o.status]||o.status}</span></span><span><b>${money(orderGross(o))}</b><small>${o.profitStatus==='received'?'✓ Received':'Pending'}</small></span><span><button class="table-primary" data-open-order="${o.id}">Manage</button></span></div>`).join('')}</div></div>`;$$('[data-open-order]').forEach(b=>b.onclick=()=>openOrder(b.dataset.openOrder))}
  async function openOrder(id){try{await refresh()}catch(e){toast(e.message);return}const o=db.orders.find(x=>x.id===id);if(!o)return;currentOrderId=id;$('#orderModalTitle').textContent=o.id;$('#orderModalContent').innerHTML=`<div class="order-detail-grid"><section class="admin-card"><h3>Customer Information</h3><div class="detail-list"><div><span>Name</span><b>${esc(o.customer?.name||'')}</b></div><div><span>Phone</span><b>${esc(o.customer?.phone||'')}</b></div><div><span>Alternative</span><b>${esc(o.customer?.altPhone||'—')}</b></div><div><span>Address</span><b>${esc([o.customer?.address,o.customer?.city,o.customer?.district].filter(Boolean).join(', '))}</b></div><div><span>Landmark</span><b>${esc(o.customer?.landmark||'—')}</b></div><div><span>Customer Note</span><b>${esc(o.customer?.notes||'—')}</b></div></div><button class="outline-btn full-btn" id="copyAtoZ">📋 Copy A to Z Order Details</button></section><section class="admin-card"><h3>Products & Profit</h3>${(o.items||[]).map(i=>`<div class="order-item-admin"><div><b>${esc(i.name)}</b><small>Qty ${i.qty} • Sell ${money(i.price)}</small></div><div><b>Gross ${money((i.price-i.supplierCost-i.shipping-i.otherCost)*i.qty)}</b><small>Net est. ${money((i.price-i.supplierCost-i.shipping-i.otherCost-i.adCost)*i.qty)}</small></div>${i.supplierUrl?`<a class="text-btn" href="${esc(i.supplierUrl)}" target="_blank">Open A to Z Product ↗</a>`:''}</div>`).join('')}<div class="profit-total"><span>Expected Gross Profit</span><strong>${money(orderGross(o))}</strong><span>Estimated Net After Ads</span><strong>${money(orderNet(o))}</strong></div></section></div><div class="order-detail-grid"><section class="admin-card"><h3>A to Z Workflow</h3><label class="field"><span>Internal Order Status</span><select id="orderStatus">${statusOptions.map(([v,l])=>`<option value="${v}" ${o.status===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field"><span>A to Z Order Number</span><input id="supplierOrderId" value="${esc(o.supplierOrderId||'')}" placeholder="Enter after submitting"></label><label class="field"><span>Admin Notes</span><textarea id="orderAdminNotes">${esc(o.adminNotes||'')}</textarea></label><button class="primary-btn full-btn" id="saveOrderWorkflow">Save Order Update</button></section><section class="admin-card"><h3>Profit Settlement</h3><div class="detail-list"><div><span>Expected Gross</span><b>${money(orderGross(o))}</b></div><div><span>Profit Status</span><b>${o.profitStatus==='received'?'Received':'Pending'}</b></div><div><span>Received Amount</span><b>${money(o.receivedProfit||0)}</b></div><div><span>Received Date</span><b>${esc(o.profitReceivedDate||'—')}</b></div></div><label class="field"><span>Amount Received</span><input id="receivedProfitInput" type="number" min="0" value="${Number(o.receivedProfit||orderGross(o))}"></label><button class="success-btn full-btn" id="markProfitReceived">✓ Mark Profit Received</button></section></div>`;openModal('orderModal');$('#copyAtoZ').onclick=()=>copyOrder(o);$('#saveOrderWorkflow').onclick=()=>{o.status=$('#orderStatus').value;o.supplierOrderId=$('#supplierOrderId').value.trim();o.adminNotes=$('#orderAdminNotes').value.trim();save();toast('Order updated');closeModal('orderModal');renderPage()};$('#markProfitReceived').onclick=()=>{o.profitStatus='received';o.receivedProfit=Number($('#receivedProfitInput').value||0);o.profitReceivedDate=new Date().toISOString().slice(0,10);save();toast('Profit marked as received');closeModal('orderModal');renderPage()}}
  async function copyOrder(o){const text=`Step in Style Order: ${o.id}\nCustomer: ${o.customer?.name||''}\nPhone: ${o.customer?.phone||''}\nAlternative Phone: ${o.customer?.altPhone||''}\nAddress: ${[o.customer?.address,o.customer?.city,o.customer?.district].filter(Boolean).join(', ')}\nLandmark: ${o.customer?.landmark||''}\n\nProducts:\n${(o.items||[]).map(i=>`${i.name} x ${i.qty} | Selling Price: ${money(i.price)} | A to Z Code: ${i.supplierCode||''}`).join('\n')}\n\nCustomer Total: ${money(o.total)}`;try{await navigator.clipboard.writeText(text);toast('Customer details copied for A to Z')}catch{prompt('Copy these details:',text)}}

  function renderReviews(){const pending=db.reviews.filter(r=>r.status==='pending').length;$('#adminContent').innerHTML=`<div class="review-stats">${statCard('All Reviews',db.reviews.length)}${statCard('Pending',pending)}${statCard('Approved',db.reviews.filter(r=>r.status==='approved').length)}${statCard('Rejected',db.reviews.filter(r=>r.status==='rejected').length)}</div><div class="filter-row"><select id="reviewFilter"><option value="all">All reviews</option><option value="pending">Pending</option><option value="approved">Approved</option><option value="rejected">Rejected</option></select></div><div id="reviewsArea"></div>`;$('#reviewFilter').onchange=renderReviewRows;renderReviewRows()}
  function renderReviewRows(){const st=$('#reviewFilter')?.value||'all',list=db.reviews.filter(r=>st==='all'||r.status===st),area=$('#reviewsArea');if(!list.length){area.innerHTML=empty('No reviews yet','Customer reviews will appear here after products are published and reviewed.');return}area.innerHTML=`<div class="table-card"><div class="admin-table review-table"><div class="tr th"><span>Customer</span><span>Product</span><span>Rating</span><span>Media</span><span>Status</span><span>Action</span></div>${list.map(r=>`<div class="tr"><span><b>${esc(r.name)}</b><small>${r.verified?'✓ Verified Purchase':'Customer review'}</small></span><span><b>${esc(productName(r.productId))}</b></span><span><span class="stars">${'★'.repeat(Number(r.rating||0))}</span></span><span>${(r.media?.images?.length||0)} photo(s) • ${(r.media?.videos?.length||0)} video(s)</span><span><span class="status-pill ${r.status}">${esc(r.status)}</span></span><span><button class="table-primary" data-open-review="${r.id}">Review</button></span></div>`).join('')}</div></div>`;$$('[data-open-review]').forEach(b=>b.onclick=()=>openReview(b.dataset.openReview))}
  function openReview(id){const r=db.reviews.find(x=>x.id===id);if(!r)return;currentReviewId=id;$('#reviewAdminContent').innerHTML=`<div class="review-admin-detail"><div class="review-meta"><span>${'★'.repeat(Number(r.rating||0))}</span><b>${esc(r.name)}</b>${r.verified?'<em>✓ Verified Purchase</em>':''}<small>Product: ${esc(productName(r.productId))}</small></div><p>${esc(r.text)}</p>${(r.media?.images||[]).length?`<div class="mini-media-grid">${r.media.images.map(src=>`<img src="${esc(src)}">`).join('')}</div>`:''}${(r.media?.videos||[]).map(src=>`<video src="${esc(src)}" controls playsinline></video>`).join('')}<label class="field"><span>Reply as Step in Style</span><textarea id="reviewReply">${esc(r.reply||'')}</textarea></label><div class="modal-actions"><button class="success-btn" id="approveReview">Approve</button><button class="outline-btn" id="rejectReview">Reject</button><button class="danger-btn" id="deleteReview">Delete</button></div></div>`;openModal('reviewAdminModal');$('#approveReview').onclick=()=>updateReview('approved');$('#rejectReview').onclick=()=>updateReview('rejected');$('#deleteReview').onclick=()=>{if(confirm('Delete this review?')){StoreDB.deleteReview(id).then(()=>{db.reviews=db.reviews.filter(x=>x.id!==id);closeModal('reviewAdminModal');renderPage()}).catch(e=>toast(e.message))}}}
  function updateReview(status){const r=db.reviews.find(x=>x.id===currentReviewId);r.status=status;r.reply=$('#reviewReply').value.trim();save();closeModal('reviewAdminModal');renderPage();toast(`Review ${status}`)}

  function renderCustomers(){if(!db.customers.length){$('#adminContent').innerHTML=empty('No customers yet','Customers will appear automatically after they place an order or create an optional account.');return}$('#adminContent').innerHTML=`<div class="table-card"><div class="admin-table customer-table"><div class="tr th"><span>Customer</span><span>Phone</span><span>Email</span><span>Orders</span><span>Last Order</span></div>${db.customers.map(c=>{const orders=db.orders.filter(o=>(o.customer?.phone||'')===(c.phone||''));const delivered=orders.filter(o=>o.status==='delivered').length,returned=orders.filter(o=>['returned','cancelled'].includes(o.status)).length;return `<div class="tr"><span><b>${esc(c.name||'Customer')}</b><small>${delivered?'⭐ Returning / delivered customer':'New customer'}${returned>=2?' • ⚠ High cancellation/return history':''}</small></span><span>${esc(c.phone||'—')}</span><span>${esc(c.email||'—')}</span><span><b>${orders.length||c.orders||0}</b><small>${delivered} delivered • ${returned} cancelled/returned</small></span><span>${formatDate(c.lastOrderAt||c.createdAt)}</span></div>`}).join('')}</div></div>`}

  function renderFinance(){const expected=db.orders.filter(o=>!['cancelled','returned'].includes(o.status)).reduce((a,o)=>a+orderGross(o),0),received=db.orders.reduce((a,o)=>a+Number(o.receivedProfit||0),0),expenses=db.expenses.reduce((a,e)=>a+Number(e.amount||0),0);$('#adminContent').innerHTML=`<div class="page-actions"><div></div><button class="primary-btn" id="addExpense">+ Add Expense</button></div><div class="kpi-grid finance-kpis">${statCard('Expected Gross Profit',money(expected))}${statCard('Received Profit',money(received),'Marked received from A to Z','success')}${statCard('Pending Profit',money(Math.max(0,expected-received)))}${statCard('Business Expenses',money(expenses))}${statCard('Net Received Profit',money(received-expenses),'Received profit − business expenses',received-expenses>=0?'success':'danger')}</div><section class="admin-card"><div class="card-head"><div><h3>Expenses</h3><p>Track Meta, TikTok, hosting and other costs.</p></div></div>${db.expenses.length?`<div class="simple-list">${db.expenses.map(e=>`<div class="expense-line"><span><b>${esc(e.category)}</b><small>${esc(e.date)} • ${esc(e.note||'')}</small></span><b>${money(e.amount)}</b><button data-delete-expense="${e.id}">Delete</button></div>`).join('')}</div>`:empty('No expenses yet','Add your first business expense when needed.')}</section>`;$('#addExpense').onclick=()=>{const f=$('#expenseForm');f.reset();f.elements.date.value=new Date().toISOString().slice(0,10);openModal('expenseModal')};$$('[data-delete-expense]').forEach(b=>b.onclick=()=>{const id=b.dataset.deleteExpense;StoreDB.deleteExpense(id).then(()=>{db.expenses=db.expenses.filter(e=>e.id!==id);renderFinance()}).catch(e=>toast(e.message))})}

  function renderReports(){$('#adminContent').innerHTML=`<div class="report-grid"><button class="report-card" data-report="orders"><b>Orders Report</b><span>Order ID, customer, amount, status and A to Z ID.</span></button><button class="report-card" data-report="sales"><b>Sales & Profit Report</b><span>Sales, expected profit and received profit.</span></button><button class="report-card" data-report="expenses"><b>Expense Report</b><span>Advertising and other business expenses.</span></button><button class="report-card" data-report="products"><b>Product Report</b><span>Views, price, A to Z cost, gross and net estimated profit.</span></button><button class="report-card" id="printReport"><b>Print Dashboard</b><span>Open the browser print dialog to save the current report as PDF.</span></button></div><section class="admin-card"><h3>Report Notes</h3><p>CSV files open directly in Excel. For PDF, use Print and choose “Save as PDF”.</p></section>`;$$('[data-report]').forEach(b=>b.onclick=()=>downloadReport(b.dataset.report));$('#printReport').onclick=()=>window.print()}
  function csvCell(v){return `"${String(v??'').replace(/"/g,'""')}"`}
  function downloadReport(type){let rows=[],name='report';if(type==='orders'){rows=[['Order ID','Date','Customer','Phone','District','Total','Status','A to Z Order','Expected Gross Profit','Received Profit'],...db.orders.map(o=>[o.id,o.date,o.customer?.name,o.customer?.phone,o.customer?.district,o.total,statusLabels[o.status]||o.status,o.supplierOrderId,orderGross(o),o.receivedProfit||0])];name='step-in-style-orders'}if(type==='sales'){rows=[['Order ID','Sales','Expected Gross Profit','Estimated Net Profit','Received Profit','Profit Status'],...db.orders.map(o=>[o.id,o.total,orderGross(o),orderNet(o),o.receivedProfit||0,o.profitStatus])];name='step-in-style-sales-profit'}if(type==='expenses'){rows=[['Date','Category','Amount','Note'],...db.expenses.map(e=>[e.date,e.category,e.amount,e.note])];name='step-in-style-expenses'}if(type==='products'){rows=[['Product','Category','Status','Views','Selling Price','Supplier Cost','Shipping','Other Cost','Ad Cost','Gross Profit','Estimated Net'],...db.products.map(p=>[p.name,p.category,p.status,p.views,p.price,p.supplierCost,p.shipping,p.otherCost,p.adCost,grossProfitProduct(p),netProfitProduct(p)])];name='step-in-style-products'}const blob=new Blob([rows.map(r=>r.map(csvCell).join(',')).join('\n')],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name+'.csv';a.click();URL.revokeObjectURL(a.href)}

  function renderAnalytics(){const published=db.products.filter(p=>p.status==='published'),views=published.reduce((a,p)=>a+Number(p.views||0),0),orders=db.orders.length,delivered=db.orders.filter(o=>o.status==='delivered').length,conv=views?orders/views*100:0;const perf=[...published].sort((a,b)=>b.views-a.views);const district={};db.orders.forEach(o=>district[o.customer?.district]=(district[o.customer?.district]||0)+1);$('#adminContent').innerHTML=`<div class="kpi-grid">${statCard('Product Views',views.toLocaleString())}${statCard('Orders',orders)}${statCard('Delivered',delivered)}${statCard('View → Order Conversion',conv.toFixed(2)+'%')}</div><div class="admin-grid-two"><section class="admin-card"><h3>Product Performance</h3>${perf.length?`<div class="simple-list">${perf.map(p=>{const count=db.orders.reduce((a,o)=>a+(o.items||[]).filter(i=>i.productId===p.id).reduce((x,i)=>x+Number(i.qty||1),0),0);return `<div class="metric-line"><span><b>${esc(p.name)}</b><small>${p.views} views • ${count} ordered</small></span><b>${money(grossProfitProduct(p))} / sale</b></div>`}).join('')}</div>`:empty('No product analytics yet','Publish products and customer activity will appear here.')}</section><section class="admin-card"><h3>Orders by District</h3>${Object.keys(district).length?`<div class="simple-list">${Object.entries(district).sort((a,b)=>b[1]-a[1]).map(([d,n])=>`<div class="metric-line"><span>${esc(d||'Unknown')}</span><b>${n}</b></div>`).join('')}</div>`:empty('No district data yet','District analytics begin after orders are placed.')}</section></div>`}

  function renderOffers(){$('#adminContent').innerHTML=`<div class="page-actions"><div><p class="muted">Active offers appear automatically on the customer home page.</p></div><button class="primary-btn" id="newOffer">+ New Offer</button></div><div id="offersAdmin"></div>`;$('#newOffer').onclick=()=>{const name=prompt('Offer name');if(!name)return;const value=Number(prompt('Discount percentage','10')||0);db.offers.unshift({id:StoreDB.uid('O'),name,type:'percent',value,active:true,start:new Date().toISOString().slice(0,10),end:''});save();renderOffers()};const wrap=$('#offersAdmin');wrap.innerHTML=db.offers.length?`<div class="simple-list">${db.offers.map(o=>`<div class="admin-card-row"><span><b>${esc(o.name)}</b><small>${o.value}% • ${o.active?'Active':'Inactive'}</small></span><div><button data-toggle-offer="${o.id}">${o.active?'Disable':'Enable'}</button><button class="danger" data-delete-offer="${o.id}">Delete</button></div></div>`).join('')}</div>`:empty('No offers yet','Create offers only when you actually want to run a promotion.');$$('[data-toggle-offer]').forEach(b=>b.onclick=()=>{const o=db.offers.find(x=>x.id===b.dataset.toggleOffer);o.active=!o.active;save();renderOffers()});$$('[data-delete-offer]').forEach(b=>b.onclick=()=>{const id=b.dataset.deleteOffer;StoreDB.deleteOffer(id).then(()=>{db.offers=db.offers.filter(x=>x.id!==id);renderOffers()}).catch(e=>toast(e.message))})}
  function renderBanners(){$('#adminContent').innerHTML=`<div class="page-actions"><div><p class="muted">Banner records are ready for future homepage campaign expansion.</p></div><button class="primary-btn" id="newBanner">+ New Banner</button></div><div id="bannersAdmin"></div>`;$('#newBanner').onclick=()=>{const title=prompt('Banner title');if(!title)return;const subtitle=prompt('Banner subtitle','')||'';db.banners.unshift({id:StoreDB.uid('BN'),title,subtitle,active:true});save();renderBanners()};const wrap=$('#bannersAdmin');wrap.innerHTML=db.banners.length?`<div class="simple-list">${db.banners.map(o=>`<div class="admin-card-row"><span><b>${esc(o.title)}</b><small>${esc(o.subtitle)}</small></span><div><button data-toggle-banner="${o.id}">${o.active?'Disable':'Enable'}</button><button class="danger" data-delete-banner="${o.id}">Delete</button></div></div>`).join('')}</div>`:empty('No banners yet','Add campaign banners when you need them.');$$('[data-toggle-banner]').forEach(b=>b.onclick=()=>{const o=db.banners.find(x=>x.id===b.dataset.toggleBanner);o.active=!o.active;save();renderBanners()});$$('[data-delete-banner]').forEach(b=>b.onclick=()=>{const id=b.dataset.deleteBanner;StoreDB.deleteBanner(id).then(()=>{db.banners=db.banners.filter(x=>x.id!==id);renderBanners()}).catch(e=>toast(e.message))})}
  function renderMedia(){const items=[];db.products.forEach(p=>{(p.media?.images||[]).forEach(src=>items.push({src,type:'image',label:p.name,kind:'Product image'}));(p.media?.videos||[]).forEach(src=>items.push({src,type:'video',label:p.name,kind:'Product video'}));(p.descriptionBlocks||[]).filter(b=>['image','video'].includes(b.type)&&b.src).forEach(b=>items.push({src:b.src,type:b.type,label:p.name,kind:'Description '+b.type}))});db.reviews.forEach(r=>{(r.media?.images||[]).forEach(src=>items.push({src,type:'image',label:productName(r.productId),kind:'Review image'}));(r.media?.videos||[]).forEach(src=>items.push({src,type:'video',label:productName(r.productId),kind:'Review video'}))});$('#adminContent').innerHTML=items.length?`<div class="media-library-grid">${items.map(m=>`<article class="media-library-card">${m.type==='image'?`<img src="${esc(m.src)}">`:videoPreview(m.src)}<b>${esc(m.kind)}</b><small>${esc(m.label)}</small></article>`).join('')}</div>`:empty('Media library is empty','Images and videos added to products, descriptions and reviews will appear here.')}
  function renderSettings(){const s=db.settings;$('#adminContent').innerHTML=`<form id="settingsForm"><section class="admin-card"><div class="store-brand-preview"><img src="assets/step-in-style-logo.png" alt="Step in Style"><div><h3>Step in Style</h3><p>Brand, phone and WhatsApp are fixed to your approved business details.</p></div></div><div class="form-grid"><label class="field"><span>Business Name</span><input value="Step in Style" disabled></label><label class="field"><span>Phone Number</span><input value="0719141519" disabled></label><label class="field"><span>WhatsApp Number</span><input value="0719141519" disabled></label><label class="field"><span>Email</span><input id="settingEmail" value="${esc(s.email)}"></label><label class="field full"><span>Tagline</span><input id="settingTagline" value="${esc(s.tagline)}"></label></div></section><section class="admin-card"><h3>Analytics IDs</h3><p class="muted">Save your Meta Pixel, TikTok Pixel and GA4 IDs when ready.</p><div class="form-grid"><label class="field"><span>Meta Pixel ID</span><input id="metaPixel" value="${esc(s.metaPixel)}"></label><label class="field"><span>TikTok Pixel ID</span><input id="tiktokPixel" value="${esc(s.tiktokPixel)}"></label><label class="field"><span>GA4 Measurement ID</span><input id="ga4" value="${esc(s.ga4)}"></label></div></section><section class="admin-card"><h3>Admin Authentication</h3><p class="muted">Admin email/password is now securely managed by Supabase Authentication, not stored in the website code. Change passwords from your Supabase Auth account.</p></section><div class="settings-actions"><button class="primary-btn">Save Settings</button><button type="button" class="danger-btn" id="resetFresh">Delete All Business Data</button></div></form>`;$('#settingsForm').onsubmit=e=>{e.preventDefault();s.email=$('#settingEmail').value.trim();s.tagline=$('#settingTagline').value.trim();s.metaPixel=$('#metaPixel').value.trim();s.tiktokPixel=$('#tiktokPixel').value.trim();s.ga4=$('#ga4').value.trim();save().then(()=>toast('Settings saved')).catch(err=>toast(err.message))};$('#resetFresh').onclick=async()=>{if(confirm('This permanently removes ALL products, orders, reviews, customers, expenses, offers and banners from Supabase. Continue?')){try{await StoreDB.resetBusinessData();db=await StoreDB.loadAdmin();renderPage();toast('Business data deleted')}catch(err){toast(err.message)}}}}


  window.addEventListener('storedb-error',e=>toast(e.detail||'Supabase save failed'));
  document.addEventListener('DOMContentLoaded',async()=>{bindShell();await loginInit()});
})();
